'use strict';
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=cents=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(cents/100);
const date=value=>new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const languageNames=new Intl.DisplayNames(undefined,{type:'language'});
function localeName(locale){try{const parsed=new Intl.Locale(locale);return `${languageNames.of(parsed.language)||parsed.language} · ${locale}`;}catch{return String(locale||'Unknown locale');}}
function countWords(value,locale='en'){try{return [...new Intl.Segmenter(locale||'en',{granularity:'word'}).segment(String(value||''))].filter(item=>item.isWordLike).length;}catch{return (String(value||'').match(/[\p{L}\p{N}]+(?:['’][\p{L}\p{N}]+)*/gu)||[]).length;}}
function readyHermesConnector(){return state.connectors.find(connector=>connector.provider==='hermes'&&connector.hasKey&&!connector.busy&&connector.test?.status==='passed');}
const viewNames={overview:'Overview',families:'Channel families',research:'Research briefs',competitors:'Competitors',niches:'Niche Factory',studio:'Content studio',production:'Production panel',connections:'Connections',progress:'Build progress'};
let state, familyFilter='', researchFamily='', productionFamily='', productionRoom='voice', selectedEvidence=new Set(), toastTimer, channelResult=null, channelQuery='', researchError='', researchPending=false, selectedConnector='';
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,6000);}
async function api(url,body,method='POST'){
  const response=await fetch(url,{method,headers:body?{'Content-Type':'application/json','X-Local-Token':state.token}:{},body:body?JSON.stringify(body):undefined});
  const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed.');return data;
}
async function refresh(){const response=await fetch('/api/state');if(!response.ok)throw new Error('The local program is unavailable. Restart it and refresh.');state=await response.json();render();}
function badge(label,color='gray'){return `<span class="chip ${color}">${esc(label)}</span>`;}
function action(label,command,id='',className='secondary'){return `<button class="button ${className}" data-action="${command}" data-id="${esc(id)}">${label}</button>`;}
function heading(title,subtitle,button=''){return `<div class="page-heading"><div><p class="eyebrow">YOUR CREATIVE OPERATIONS</p><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`;}
function activeFamilies(){return state.families.filter(f=>!f.archived);}
function familyName(id){return state.families.find(f=>f.id===id)?.name||'Unknown family';}
function empty(title,description,button='',icon='▦'){return `<div class="empty"><span class="empty-icon">${icon}</span><h3>${title}</h3><p>${description}</p>${button}</div>`;}
function stats(){const families=activeFamilies(),drafts=state.contents.filter(c=>families.some(f=>f.id===c.familyId)),slots=families.reduce((count,family)=>count+family.channels.length,0);return `<div class="stats">${[
  ['Channel families',families.length,'Of your planned 10–15 families','▦'],['Language slots',slots,'Chosen per family; one or more','文'],['Content drafts',drafts.length,`${drafts.filter(c=>c.state==='in_review').length} awaiting your review`,'✎'],['Planned monthly budget',money(families.reduce((n,f)=>n+f.budgetCents,0)),'Bounded script and research token gates','$']
].map(([label,value,note,icon])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>`;}
function overview(){
  const families=activeFamilies();
  return heading('A little structure. A lot of possibility.','One workspace for your ideas, channel families and next production steps.',action('+ Create a family','new-family','','primary'))+stats()+
  `<div class="overview-grid"><div><section class="panel"><div class="panel-header"><h2>Your channel portfolio</h2>${badge(`${families.reduce((count,family)=>count+family.channels.length,0)} chosen language slots`)}</div>${families.length?`<div class="panel-body">${families.slice(0,4).map(f=>`<div class="step"><span class="step-number">${esc(f.name.charAt(0).toUpperCase())}</span><div><h3>${esc(f.name)} ${badge(`Tier ${f.tier}`)}</h3><p>${esc(f.countries.join(' · '))} · ${f.cadence} originals / week · ${f.channels.map(channel=>esc(channel.locale)).join(', ')}</p>${action('Open drafts →','family-drafts',f.id,'text-button')}</div></div>`).join('')}</div>`:empty('Start with one strong channel family.','Define an audience, a primary content language, and any optional additional channel languages.',action('+ Create your first family','new-family','','primary'))}</section>
  <section class="panel"><div class="panel-header"><h2>Recent workspace activity</h2>${badge('Saved locally')}</div><div class="panel-body">${state.events.length?`<ul class="activity">${state.events.slice(0,5).map(e=>`<li>${esc(e.message)}<time>${esc(date(e.created_at))}</time></li>`).join('')}</ul>`:`<p class="muted">Your saved changes and completed planning jobs will appear here.</p>`}</div></section></div>
  <div><section class="panel"><div class="panel-header"><h2>Your first production loop</h2><span class="stage-label">START HERE</span></div><div class="panel-body">${[
    ['Define the audience','Choose a market profile, languages, format and budget.',families.length>0],['Write an original, sourced draft','Record an angle, hook, primary-language script and evidence.',state.contents.length>0],['Review the primary script','Approve the exact version before moving forward.',state.contents.some(c=>c.state==='approved')],['Prepare a storyboard','Create an editable planning export for six scenes.',state.contents.some(c=>c.scenes.length)]
  ].map(([label,description,done],i)=>`<div class="step ${done||i===0?'current':''}"><span class="step-number">${done?'✓':String(i+1).padStart(2,'0')}</span><div><h3>${label}</h3><p>${description}</p></div></div>`).join('')}</div></section>
  <div class="notice"><span class="notice-icon">◈</span><div><strong>Research and script reasoning are review-gated.</strong><p>Saved evidence can produce immutable daily briefs, and Hermes can propose quality-checked candidates in each family’s primary locale. Voice, optional localization, rendering and publishing remain upcoming.</p><a class="button text-button" href="#progress">View the build roadmap →</a></div></div></div></div>`;
}
function localPeriod(family){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:family.timezone,year:'numeric',month:'2-digit'}).formatToParts(new Date()).map(part=>[part.type,part.value]));return `${parts.year}-${parts.month}`;}
function tokenSummary(familyId){const family=state.families.find(item=>item.id===familyId),period=family?localPeriod(family):'',rows=state.usage.filter(item=>item.familyId===familyId&&item.period===period),settled=rows.filter(item=>item.status==='settled').reduce((sum,item)=>sum+(item.totalTokens||0),0),reserved=rows.filter(item=>item.status!=='settled'&&item.status!=='released').reduce((sum,item)=>sum+Math.max(item.reservedTokens||0,item.totalTokens||0),0);return {limit:family?.tokenBudget?.monthlyLimit||0,settled,reserved,period};}
function competitorSummary(f){const list=f.competitors||[],count=list.length,ready=count>=3;return `<div class="competitor-strip"><div class="card-top"><span class="micro-label">Competitor channels</span>${badge(count?`${count} linked`:'None yet',ready?'green':count?'orange':'gray')}</div>${count?`<p>${list.map(item=>`<a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">${esc(item.kind==='username'?item.url.replace('https://www.youtube.com/',''):item.value)}</a>`).join(' · ')}</p>`:''}${ready?'':`<p class="hint">Add ${count?`${3-count} more`:'3-10'} competitor channel${count===2?'':'s'} so Competitor Intelligence can learn from them.</p>`}</div>`;}
function familyCard(f){const tokens=tokenSummary(f.id);return `<article class="family-card"><div class="card-top">${badge(`Tier ${f.tier}`)}${badge(f.archived?'Archived':'Planning',f.archived?'gray':'green')}</div><h2>${esc(f.name)}</h2><p>${esc(f.countries.join(' · '))}</p><p>${esc(f.audience)}</p><div class="languages">${f.channels.map((c,index)=>`<span>${esc(localeName(c.locale))}${index===0?' · Primary':''} · ${esc(c.connection.replaceAll('_',' '))}</span>`).join('')}</div>${competitorSummary(f)}<div class="card-meta"><span>${f.cadence} originals / week</span><span>${money(f.budgetCents)} / month</span><span>${tokens.settled.toLocaleString()} used + ${tokens.reserved.toLocaleString()} reserved / ${tokens.limit.toLocaleString()} tokens</span></div><div class="card-actions">${action('Edit','edit-family',f.id,'text-button')}${!f.archived?action('View drafts →','family-drafts',f.id,'text-button'):''}${action(f.archived?'Restore':'Archive',f.archived?'restore-family':'archive-family',f.id,'text-button danger')}</div></article>`;}
function families(){return heading('Channel families','One original brand with one primary language and any optional additional editions you choose.',action('+ Create a family','new-family','','primary'))+stats()+`<div class="family-grid">${state.families.map(familyCard).join('')||`<div class="panel full-span">${empty('Your portfolio starts here.','Create one family and choose one or more content languages.',action('+ Create a family','new-family','','primary'))}</div>`}</div>`;}
function localDay(family){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:family.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(part=>[part.type,part.value]));return `${parts.year}-${parts.month}-${parts.day}`;}
function evidenceLinks(ids,snapshot){return ids.map(id=>{const source=snapshot.find(item=>item.id===id);return source?`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(id)} · ${esc(source.title)}</a>`:esc(id);}).join(', ');}
function retryAllowed(job){const usage=state.usage.find(item=>item.jobId===job.id),paid=['settled','unknown','budget_violation'].includes(usage?.status);return ['failed','stale','cancelled','interrupted','quality_failed','usage_unknown','budget_violation','blocked_budget'].includes(job.status)&&(!paid||job.attempts<3);}
function researchJobRow(job){return `<div class="inline-warning">${esc(job.brief_date)} · ${esc(job.status)} · paid attempt ${job.attempts}/3${job.error?' · '+esc(job.error):''}${retryAllowed(job)?action('Retry research','retry-research',job.id,'text-button'):''}</div>${job.decision==='no_strong_topic'?`<div class="checks"><strong>No strong topic</strong><p>${esc(job.rationale)}</p><p class="muted">Review-only decision. No draft or publishing action was created.</p></div>`:''}`;}
function researchBriefCard(brief){const topic=brief.payload,job=state.researchJobs.find(item=>item.id===brief.jobId);return `<article class="draft-card"><div class="card-top">${badge(brief.status==='review_only'?'Review only':'Quality blocked',brief.status==='review_only'?'green':'orange')}<span class="muted">${esc(brief.briefDate)}</span></div><h2>${esc(topic.title)}</h2>${job?.rationale?`<p><strong>Research decision:</strong> ${esc(job.rationale)}</p>`:''}<p><strong>Audience need:</strong> ${esc(topic.audienceNeed)}</p><p><strong>Why now:</strong> ${esc(topic.whyNow.text)} · ${evidenceLinks(topic.whyNow.sourceIds,brief.evidenceSnapshot)}</p><p><strong>Original angle:</strong> ${esc(topic.angle)}</p><div class="checks"><strong>Hooks</strong><ul>${topic.hooks.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div><div class="checks"><strong>Outline</strong><ol>${topic.outline.map(item=>`<li>${esc(item)}</li>`).join('')}</ol></div><div class="checks"><strong>Evidence claims</strong><ul>${topic.evidenceClaims.map(claim=>`<li>${esc(claim.text)} · ${evidenceLinks(claim.sourceIds,brief.evidenceSnapshot)}</li>`).join('')}</ul></div><p><strong>Confidence:</strong> ${esc(topic.confidence.level)}. ${esc(topic.confidence.rationale)}</p><div class="checks"><strong>Missing evidence</strong>${topic.confidence.missingEvidence.length?`<ul>${topic.confidence.missingEvidence.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<p>None reported.</p>'}</div><div class="checks"><strong>Uncertainties</strong>${topic.uncertainties.length?`<ul>${topic.uncertainties.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<p>None reported.</p>'}</div>${brief.quality.issues.length?`<div class="checks"><strong>Quality issues</strong><ul>${brief.quality.issues.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`:''}<p class="muted">Expires ${esc(topic.expiresAt)}. Immutable research artifact. It does not create a draft or authorize publication.</p></article>`;}
function research(){
  const families=activeFamilies();if(!families.length)return heading('Research briefs','Dated evidence becomes review-only topic opportunities.')+`<section class="panel">${empty('Create a family first.','Research stays scoped to one channel family and its audience.',action('+ Create a family','new-family','','primary'))}</section>`;
  if(!families.some(item=>item.id===researchFamily))researchFamily=families[0].id;
  const family=families.find(item=>item.id===researchFamily),today=localDay(family),evidence=state.researchEvidence.filter(item=>item.familyId===family.id),eligible=evidence.filter(item=>!item.archived&&item.permission==='permitted'&&item.analysisMode==='brief_synthesis_permitted'&&item.expiresAt>=today),jobs=state.researchJobs.filter(item=>item.family_id===family.id),briefs=state.topicBriefs.filter(item=>item.familyId===family.id),connector=readyHermesConnector(),tokens=tokenSummary(family.id);
  selectedEvidence=new Set([...selectedEvidence].filter(id=>eligible.some(item=>item.id===id)));
  return heading('Research briefs','Daily, dated, evidence-linked topic opportunities. Review only, never auto-drafted or published.',action('+ Add evidence','new-evidence','','primary'))+
    `<div class="filters"><label for="research-family">Family</label><select id="research-family">${families.map(item=>`<option value="${item.id}" ${item.id===family.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select><span class="muted">Family-local date ${esc(today)}</span></div>
    <section class="panel"><div class="panel-header"><h2>Evidence library</h2>${badge(`${eligible.length} eligible`,'green')}</div><div class="panel-body"><p>Select 1-20 current records. URLs are stored for provenance, not fetched by Hermes.</p><div class="content-list">${evidence.map(item=>`<article class="research-result"><div class="card-top"><label class="checkbox-label"><input class="brief-evidence" type="checkbox" value="${item.id}" ${selectedEvidence.has(item.id)?'checked':''} ${eligible.includes(item)?'':'disabled'}><strong>${esc(item.title)}</strong></label>${badge(item.archived?'Archived':item.expiresAt<today?'Expired':eligible.includes(item)?'Synthesis permitted':'Display only',eligible.includes(item)?'green':'gray')}</div><p>${esc(item.publisher)} · accessed ${esc(item.accessedAt)} · expires ${esc(item.expiresAt)} · v${item.revision}</p><p>${esc(item.notes)}</p><p><a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a></p><div class="card-actions">${action('Edit','edit-evidence',item.id,'text-button')}${action(item.archived?'Restore':'Archive',item.archived?'restore-evidence':'archive-evidence',item.id,'text-button danger')}</div></article>`).join('')||'<p class="muted">No saved research evidence yet.</p>'}</div><div class="draft-actions">${connector?action('Prepare daily brief','prepare-research',family.id,'primary'):''}</div><p class="hint">${tokens.settled.toLocaleString()} settled + ${tokens.reserved.toLocaleString()} reserved of ${tokens.limit.toLocaleString()} tokens for ${tokens.period}. Research reserves up to ${family.tokenBudget.researchJobLimit.toLocaleString()} tokens per request.</p></div></section>
    <section class="panel"><div class="panel-header"><h2>Daily jobs</h2>${badge('Manual queue')}</div><div class="panel-body">${jobs.map(researchJobRow).join('')||'<p class="muted">No research jobs for this family.</p>'}</div></section>
    <div class="content-list">${briefs.map(researchBriefCard).join('')||`<section class="panel">${empty(jobs.some(job=>job.decision==='no_strong_topic')?'No topic briefs selected.':'No topic briefs yet.',jobs.some(job=>job.decision==='no_strong_topic')?'Hermes recorded a no-strong-topic decision above. Review its rationale rather than forcing a weak idea.':'Add permitted evidence, select it, then prepare today’s review-only brief.')}</section>`}</div>${!connector?'<div class="notice"><span class="notice-icon">◈</span><div><strong>Hermes connector required.</strong><p>Add and test a tool-free Hermes reasoning connector in Connections before preparing a brief.</p></div></div>':''}`;
}
function draftCard(c){
  const family=state.families.find(f=>f.id===c.familyId),archived=family?.archived;
  const labels={draft:'Draft',in_review:'In review',approved:'Script approved'};
  const jobs=state.jobs.filter(j=>j.content_id===c.id&&j.revision===c.revision&&(!j.type.startsWith('hermes_script:')||j.scopeCurrent!==false));
  const hermesConnector=readyHermesConnector();
  const hasCurrentHermesPath=jobs.some(job=>job.type.startsWith('hermes_script:'));
  const candidates=state.scriptCandidates.filter(candidate=>candidate.contentId===c.id&&candidate.contentRevision===c.revision);
  return `<article class="draft-card"><div class="card-top"><span class="muted">${esc(familyName(c.familyId))} · ${esc(localeName(family?.primaryLocale))} master · v${c.revision}</span>${badge(labels[c.state],c.state==='approved'?'green':c.state==='in_review'?'orange':'gray')}</div><h2>${esc(c.title)}</h2><p>${esc(c.angle||'Add the original angle to begin shaping this story.')}</p><p>${countWords(c.script,family?.primaryLocale)} words · ${c.sources.length} source${c.sources.length===1?'':'s'} · ${c.kind==='fiction'?'Original fiction':'Factual / educational'}</p>
    ${c.reviewIssues.length?`<div class="checks"><strong>Before this draft can enter review</strong><ul>${c.reviewIssues.map(issue=>`<li>${esc(issue)}</li>`).join('')}</ul></div>`:''}
    ${c.state==='in_review'?'<div class="checks">Read the full script and evidence using “Review draft.” Approving confirms this exact primary-language script version only.</div>':''}
    <div class="draft-actions">${!archived?action(c.state==='in_review'?'Review draft':'Edit draft','edit-content',c.id):badge('Family archived')}${!archived&&hermesConnector&&!hasCurrentHermesPath?action('Ask Hermes','hermes-script',c.id,'secondary'):''}${!archived&&c.state==='draft'?action('Submit for review','submit-content',c.id,'primary'):''}${!archived&&c.state==='in_review'?action('Approve script','approve-content',c.id,'primary')+action('Return to draft','return-content',c.id):''}${!archived&&c.state==='approved'&&!c.scenes.length?action('Prepare storyboard','storyboard',c.id,'primary'):''}<a class="button text-button" href="/api/content/${c.id}/export">Export planning file ↓</a></div>
    ${jobs.map(job=>`<div class="inline-warning">${job.type.startsWith('hermes_script:')?`Hermes script job: ${esc(job.status)} · paid attempt ${job.attempts||1}/3${job.error?' · '+esc(job.error):''}${retryAllowed(job)?action('Retry Hermes','retry-hermes',job.id,'text-button'):''}`:`Storyboard job: ${esc(job.status)}${job.error?' · '+esc(job.error):''}`}</div>`).join('')}
    ${candidates.map(candidate=>`<details class="scenes" open><summary>Hermes ${esc(candidate.locale)} candidate · ${candidate.status==='available'?'quality passed':'quality blocked'}</summary><h3>${esc(candidate.payload.title)}</h3><div class="card-top">${badge(candidate.quality.passed?'Quality passed':'Quality blocked',candidate.quality.passed?'green':'orange')}<span class="muted">${candidate.quality.wordCount} words · target ${esc(candidate.quality.targetWords)} · ${candidate.usage.totalTokens??'Unknown'} tokens</span></div>${candidate.quality.issues.length?`<div class="checks"><strong>Quality gate</strong><ul>${candidate.quality.issues.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`:''}<p><strong>Angle:</strong> ${esc(candidate.payload.angle)}</p><p><strong>Hook:</strong> ${esc(candidate.payload.hook)}</p><p>${esc(candidate.payload.script)}</p>${candidate.payload.claims.length?`<div class="checks"><strong>Claims and supplied Source IDs</strong><ul>${candidate.payload.claims.map(claim=>`<li>${esc(claim.text)} <strong>Sources:</strong> ${claim.sourceIds.map(id=>{const source=c.sources[Number(id.slice(1))-1];return source?`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(id)} · ${esc(source.title)}</a>`:esc(id);}).join(', ')}</li>`).join('')}</ul></div>`:''}${candidate.payload.uncertainties.length?`<div class="checks"><strong>Uncertainties</strong><ul>${candidate.payload.uncertainties.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`:''}<p class="muted">Generated for content v${candidate.contentRevision}; not approved and not published.</p>${candidate.status==='available'?action('Use candidate','use-hermes-candidate',candidate.id,'primary'):'<p class="inline-warning">This paid output is retained for diagnosis but cannot be copied into the draft.</p>'}</details>`).join('')}
    ${c.scenes.length?`<details class="scenes"><summary>${c.scenes.length}-scene planning scaffold · ${esc(family?.primaryLocale)} ready for direction</summary><p>Scene breaks and timing are rough planning estimates, not AI-directed scenes or generated video. Adjust breaks before narration. <a href="/api/templates/stickman" target="_blank" rel="noopener">Read the directing reference ↗</a></p><div class="languages">${c.editions.map(e=>`<span>${esc(localeName(e.locale||e.language))} · ${esc(e.state.replaceAll('_',' '))}</span>`).join('')}</div><div class="scene-grid">${c.scenes.map(s=>`<div class="scene"><strong>${s.order}. ${esc(s.purpose)} · ~${s.durationEstimateSeconds}s</strong><p>${esc(s.narration)}</p><small class="muted">Visual direction and performance cues still need review.</small></div>`).join('')}</div></details>`:''}</article>`;
}
function studio(){const filtered=state.contents.filter(c=>!familyFilter||c.familyId===familyFilter);return heading('Content studio','Original ideas, clear evidence and one approved primary-language master.',action('+ New draft','new-content','','primary'))+`<div class="filters"><label for="family-filter">Family</label><select id="family-filter"><option value="">All families</option>${state.families.map(f=>`<option value="${f.id}" ${f.id===familyFilter?'selected':''}>${esc(f.name)}${f.archived?' (archived)':''}</option>`).join('')}</select><span class="muted">${filtered.length} saved draft${filtered.length===1?'':'s'}</span></div><div class="content-list">${filtered.map(draftCard).join('')||`<div class="panel">${empty('Make your first story worth telling.','Save an original angle, hook and evidence. Drafts can stay incomplete until you are ready to review.',action(activeFamilies().length?'+ Write a draft':'+ Create a family',activeFamilies().length?'new-content':'new-family','','primary'),'✎')}</div>`}</div>`;}
const productionRooms=[
  {id:'script',number:'01',name:'Script & Brief Room',status:'live',summary:'Approved primary-locale source'},
  {id:'voice',number:'02',name:'Voice Room',status:'live',summary:'Narration identity and performance'},
  {id:'style',number:'03',name:'Style Library & Assignment Room',status:'active',summary:'Family visual grammar'},
  {id:'scene',number:'04',name:'Scene & Visual Room',status:'locked',summary:'Shot manifests and rights'},
  {id:'editing',number:'05',name:'Editing Room',status:'locked',summary:'Timeline, cuts and finishing'},
  {id:'captions',number:'06',name:'Captions & Localization Room',status:'locked',summary:'Timed language editions'},
  {id:'audio',number:'07',name:'Audio Room',status:'locked',summary:'Mix, music and sound'},
  {id:'qc',number:'08',name:'Review & QC Room',status:'locked',summary:'Technical and editorial release gate'},
  {id:'packaging',number:'09',name:'Packaging Room',status:'locked',summary:'Title, description and thumbnail'},
  {id:'render',number:'10',name:'Render & Recovery Room',status:'locked',summary:'Deterministic final artifacts'}
];
const roomBlueprints={
  script:{purpose:'Locks the reviewed editorial source that every production artifact must trace back to.',settings:['Content format and audience promise','Evidence and rights review','Primary locale and exact script revision','Human editorial approval'],inputs:['Saved evidence','Review-only topic brief','Original draft'],outputs:['Approved immutable script','Source snapshot','Primary-locale production gate']},
  style:{purpose:'Defines the family editing language inherited by its channel editions.',settings:['Five launch style profiles','Typography, palette and motion grammar','Shot density and transition policy','Channel override approval trail'],inputs:['Approved narration','Audience and format','Licensed brand assets'],outputs:['Versioned family style assignment','Renderer constraints','Visual acceptance checklist']},
  scene:{purpose:'Turns locked narration into rights-safe shots without silently choosing a renderer.',settings:['Scene timing and shot purpose','Asset source and commercial rights','Camera, motion and continuity rules','Versioned model capability and media-role limits','Cost, polling, cancellation and fallback policy'],inputs:['Approved narration handoff','Style assignment','Rights-reviewed immutable assets'],outputs:['Versioned scene manifest','Asset and synthetic-media provenance ledger','Checksummed generation runs and proxy-ready shot plan']},
  editing:{purpose:'Builds the advanced deterministic timeline for cuts, grades, ramps, merges, audio sync and final editorial polish.',settings:['Cut, trim, ripple and linked A/V policy','Transitions, speed ramps and keyframes','Color correction, grading, LUT and scopes','Multitrack sync, multicam, captions and markers','Proxy, render queue, undo and recovery policy','Lossless conform, remux and interchange rules'],inputs:['Narration-timed scenes','Proxy media and rights ledger','Style and audio direction'],outputs:['Revisioned edit decision timeline','Preview render and QC markers','Conform-ready media manifest']},
  captions:{purpose:'Produces reviewed timed text and independent locale editions only after the master is locked.',settings:['Transcript source and alignment tolerance','Reading speed and line-break policy','Visible-text translation review','Edition-specific retry and approval'],inputs:['Locked master narration','Edit timing','Locale configuration'],outputs:['Approved timed captions','Localized text manifests','Independent edition handoffs']},
  audio:{purpose:'Creates a licensed, intelligible and measurable final mix.',settings:['Dialogue, music and SFX buses','Ducking and automation curves','Loudness and true-peak targets','Music and sound-effect rights'],inputs:['Approved narration','Locked edit timing','Licensed audio assets'],outputs:['Versioned mix stems','Loudness report','Rights-complete master mix']},
  qc:{purpose:'Combines editorial review and full technical decode before release.',settings:['Frame, cut and visible-text checks','Transcript and intelligibility review','Black, freeze, silence and clipping thresholds','Stale-artifact and rights blockers'],inputs:['Preview or final render','Captions and mix','Complete provenance graph'],outputs:['Signed QC decision','Issue list with timecodes','Release gate or repair handoff']},
  packaging:{purpose:'Builds reviewable channel packaging without mutating approved content.',settings:['Title and description variants','Thumbnail composition and safe areas','Claim and source consistency','Per-channel language and metadata'],inputs:['Approved master','Channel identity','Rights-cleared stills'],outputs:['Approved package revision','Thumbnail artifact','Publishing attachment manifest']},
  render:{purpose:'Creates reproducible deliverables and recovers safely from interrupted work.',settings:['Pinned codec and container','Resolution, frame rate and color space','Proxy and final presets','Checksums, logs and resume points'],inputs:['Locked timeline','Approved mix and captions','Packaging manifest'],outputs:['Checksummed master file','Render evidence and logs','Upload-ready handoff']}
};
function productionBlueprint(room){const blueprint=roomBlueprints[room.id];if(room.id==='script')return `<section class="production-stage locked-stage"><div class="stage-kicker">FOUNDATION ROUTE</div><h2>Script & Brief Room</h2><p>${blueprint.purpose}</p><div class="handoff-columns"><div><span class="micro-label">Inputs & gate</span><ul>${blueprint.inputs.map(item=>`<li>${item}</li>`).join('')}</ul></div><div><span class="micro-label">Output handoff</span><ul>${blueprint.outputs.map(item=>`<li>${item}</li>`).join('')}</ul></div></div><a class="button primary" href="#studio">Open Content Studio</a></section>`;return `<section class="production-stage locked-stage"><div class="locked-watermark">${room.number}</div><div class="stage-kicker">CONTROL CONTRACT READY · RUNTIME LOCKED</div><h2>${esc(room.name)}</h2><p>${blueprint.purpose}</p><div class="room-contract-grid"><div><span class="micro-label">Detailed channel settings</span><ul>${blueprint.settings.map(item=>`<li>${item}</li>`).join('')}</ul></div><div><span class="micro-label">Inputs & gate</span><ul>${blueprint.inputs.map(item=>`<li>${item}</li>`).join('')}</ul></div><div><span class="micro-label">Output handoff</span><ul>${blueprint.outputs.map(item=>`<li>${item}</li>`).join('')}</ul></div></div><div class="room-lock-note"><strong>Milestone locked.</strong> The contract is visible, but no provider, editor, renderer or publisher becomes active before this room is implemented and tested.</div></section>`;}
function voiceJobRetryable(job){const usage=state.voiceUsage.find(item=>item.jobId===job.id),paid=['settled','unknown'].includes(usage?.status);return ['failed','interrupted','validation_failed','blocked_budget'].includes(job.status)&&(!paid||job.attempts<3);}
function voiceUsageSummary(family){const period=localPeriod(family),rows=state.voiceUsage.filter(item=>item.familyId===family.id&&item.period===period),settled=rows.filter(item=>item.status==='settled').reduce((sum,item)=>sum+(item.settledCharacters||item.reservedCharacters),0),reserved=rows.filter(item=>['reserved','unknown'].includes(item.status)).reduce((sum,item)=>sum+item.reservedCharacters,0),cost=rows.filter(item=>['reserved','settled','unknown'].includes(item.status)).reduce((sum,item)=>sum+(item.estimatedCostCents||0),0);return {period,settled,reserved,cost};}
function voiceProfileDialog(family){const form=$('#voice-profile-form'),profiles=state.voiceProfiles.filter(item=>item.familyId===family.id),profile=profiles.at(-1),connectors=state.connectors.filter(item=>['openai','elevenlabs'].includes(item.provider)&&item.hasKey&&!item.busy&&item.test?.status==='passed');form.reset();form.querySelector('.form-error').hidden=true;form.elements.familyId.value=family.id;form.elements.familyRevision.value=family.revision;form.elements.revision.value=profile?.revision||0;form.elements.connectorId.innerHTML=connectors.map(item=>`<option value="${item.id}">${esc(item.name)} · ${esc(state.connectorProviders[item.provider].name)}</option>`).join('');if(!connectors.length){toast('Add and test an OpenAI or ElevenLabs connector first.',true);location.hash='connections';return;}const connector=connectors.find(item=>item.id===profile?.connectorId)||connectors[0];form.elements.connectorId.value=connector.id;form.elements.provider.value=connector.provider;if(profile){form.elements.name.value=profile.name;form.elements.model.value=profile.model;form.elements.voiceId.value=profile.voiceId;form.elements.voiceVersion.value=profile.voiceVersion;form.elements.ownershipBasis.value=profile.rights.ownershipBasis;form.elements.rightsHolder.value=profile.rights.rightsHolder;form.elements.evidenceReference.value=profile.rights.evidenceReference;form.elements.termsReviewedAt.value=profile.rights.termsReviewedAt;for(const key of ['pace','energy','emotion','pauseScale','emphasis','stability','similarity','style','instructions'])form.elements[key].value=profile.delivery[key];form.elements.lexicon.value=profile.lexicon.entries.map(item=>`${item.term} => ${item.replacement}${item.notes?' | '+item.notes:''}`).join('\n');for(const key of ['monthlyCharacterLimit','maxCharactersPerAudition','priceCentsPerMillionCharacters'])form.elements[key].value=profile.budget[key];form.elements.consentConfirmed.checked=profile.rights.consentConfirmed;form.elements.commercialUseConfirmed.checked=profile.rights.commercialUseConfirmed;}else{form.elements.name.value='Primary narrator';form.elements.model.value=connector.provider==='openai'?'gpt-4o-mini-tts':'eleven_multilingual_v2';form.elements.voiceVersion.value='provider-current';form.elements.termsReviewedAt.value=new Date().toISOString().slice(0,10);}$('#voice-profile-dialog').showModal();}
function voiceApprovalDialog(id){const audition=state.voiceAuditions.find(item=>item.id===id);if(!audition)return toast('That audition is no longer available.',true);const form=$('#voice-approval-form');form.reset();form.querySelector('.form-error').hidden=true;form.elements.auditionId.value=id;$('#voice-approval-heading').textContent=`Approve take ${id.slice(0,8)}`;$('#voice-approval-dialog').showModal();}
function voiceRevokeDialog(id){const approval=state.voiceApprovals.find(item=>item.id===id&&item.status==='approved');if(!approval)return toast('That narration approval is no longer active.',true);const form=$('#voice-revoke-form');form.reset();form.querySelector('.form-error').hidden=true;form.elements.approvalId.value=id;$('#voice-revoke-dialog').showModal();}
function voiceRoom(family){
  const profiles=state.voiceProfiles.filter(item=>item.familyId===family.id),profile=profiles.at(-1),contents=state.contents.filter(item=>item.familyId===family.id&&item.state==='approved'),jobs=state.voiceJobs.filter(item=>item.family_id===family.id),auditions=state.voiceAuditions.filter(item=>item.familyId===family.id),approvals=state.voiceApprovals.filter(item=>item.familyId===family.id),handoffs=state.voiceHandoffs.filter(item=>item.familyId===family.id),currentApproval=approvals.find(item=>item.status==='approved'),usage=voiceUsageSummary(family),connector=profile&&state.connectors.find(item=>item.id===profile.connectorId&&item.revision===profile.connectorRevision&&item.test?.status==='passed'&&!item.busy),ffmpegReady=state.capabilities.ffmpeg==='executable_detected';
  const profilePanel=profile?`<div class="voice-identity"><div class="voice-orb">${esc(profile.name.charAt(0).toUpperCase())}</div><div><div class="card-top"><h2>${esc(profile.name)}</h2>${badge(`Profile v${profile.revision}`,'green')}</div><p>${esc(profile.provider)} · ${esc(profile.model)} · ${esc(profile.voiceId)} · ${esc(profile.locale)}</p><p class="muted">${esc(profile.rights.ownershipBasis.replaceAll('_',' '))} · rights holder ${esc(profile.rights.rightsHolder)} · terms reviewed ${esc(profile.rights.termsReviewedAt)}</p></div></div><div class="voice-setting-grid"><div><span>Delivery direction</span><strong>${esc(profile.delivery.emotion)} · ${profile.delivery.pace}× pace</strong><small>Energy ${profile.delivery.energy} · emphasis ${profile.delivery.emphasis} · pause ${profile.delivery.pauseScale}×</small></div><div><span>Pronunciation lexicon</span><strong>v${esc(profile.lexicon.versionId.slice(0,8))} · ${profile.lexicon.entries.length} entries</strong><small>${profile.lexicon.entries.map(item=>`${esc(item.term)} → ${esc(item.replacement)}`).join(' · ')||'No overrides'}</small></div><div><span>Cost controls</span><strong>${profile.budget.monthlyCharacterLimit.toLocaleString()} chars / month</strong><small>${profile.budget.maxCharactersPerAudition.toLocaleString()} max per audition · estimated ${money(profile.budget.priceCentsPerMillionCharacters)} / 1M chars</small></div><div><span>Voice ownership & commercial use</span><strong>Consent and commercial use confirmed</strong><small>${esc(profile.rights.evidenceReference)}</small></div></div>`:`<div class="production-empty"><span class="empty-icon">◉</span><h2>No primary narrator configured</h2><p>Create the immutable voice identity, provider provenance, consent record, delivery direction, lexicon and cost gate for ${esc(family.name)}.</p></div>`;
  const contentRows=contents.map(content=>{const handoff=handoffs.find(item=>item.contentId===content.id),busy=jobs.some(item=>item.content_id===content.id&&['queued','running'].includes(item.status));return `<article class="production-row"><div><span class="micro-label">APPROVED SCRIPT · v${content.revision}</span><h3>${esc(content.title)}</h3><p>${countWords(content.script,family.primaryLocale).toLocaleString()} words · ${content.script.length.toLocaleString()} source characters · ${esc(localeName(family.primaryLocale))}</p></div><div class="row-end">${handoff?.ready?badge('Narration approved','green'):badge(busy?'Audition running':'Needs narration',busy?'orange':'gray')}${profile&&connector&&ffmpegReady&&!busy&&!handoff?.ready?action('Generate audition','queue-voice',content.id,'primary'):''}</div></article>`;}).join('')||`<div class="production-empty compact"><h3>No approved script input</h3><p>Approve a current primary-locale script in Content Studio. Drafts and stale revisions cannot enter the Voice Room.</p><a class="button secondary" href="#studio">Open Content Studio</a></div>`;
  const jobRows=jobs.slice(0,8).map(job=>`<div class="voice-job"><span class="job-dot ${esc(job.status)}"></span><div><strong>${esc(job.status.replaceAll('_',' '))}</strong><small>Paid attempt ${job.attempts}/3${job.error?' · '+esc(job.error):''}</small></div>${voiceJobRetryable(job)?action('Retry deliberately','retry-voice',job.id,'text-button'):''}</div>`).join('')||'<p class="muted">No narration jobs yet. Generation only starts after an explicit click.</p>';
  const auditionCards=auditions.map(audition=>{const approval=approvals.find(item=>item.auditionId===audition.id&&item.status==='approved'),analysis=audition.analysis,checks=analysis.checks||[];return `<article class="audition-card ${approval?'selected':''}"><div class="card-top">${badge(approval?'Approved take':audition.status,approval?'green':audition.status==='validated'?'orange':'gray')}<span class="mono">${esc(audition.id.slice(0,8))}</span></div><audio controls preload="metadata" src="/api/voice-auditions/${audition.id}/audio"></audio><div class="audio-metrics"><span><strong>${Number(analysis.durationSeconds).toFixed(1)}s</strong>duration</span><span><strong>${Math.round((analysis.silenceRatio||0)*100)}%</strong>silence</span><span><strong>${analysis.maxVolumeDb??'?'}</strong>peak dB</span><span><strong>${analysis.integratedLoudnessLufs??'?'}</strong>LUFS</span></div><p class="muted">${esc(audition.provider.model)} · ${esc(audition.provider.voiceId)} · profile v${audition.profileRevision} · ${esc(audition.artifact.sha256.slice(0,12))}</p>${checks.length?`<div class="qc-checks">${checks.map(check=>`<span class="${check.passed?'pass':'fail'}">${check.passed?'✓':'!'} ${esc(check.name)}</span>`).join('')}</div>`:''}<div class="card-actions">${!approval&&audition.status==='validated'&&audition.scopeCurrent?action('Compare & approve','approve-voice',audition.id,'primary'):''}${approval?action('Revoke handoff','revoke-voice',approval.id,'text-button danger'):''}</div></article>`;}).join('')||'<div class="production-empty compact"><h3>No immutable auditions yet</h3><p>Each take will retain its script, profile, provider, model, voice, request IDs, cost admission, checksum and real-audio QC.</p></div>';
  const invalidations=state.productionInvalidations.filter(item=>item.familyId===family.id).slice(-12).reverse();
  return `<section class="voice-hero"><div><span class="stage-kicker">ROOM 02 · PRIMARY MASTER</span><h2>Voice Room</h2><p>Lock a legally usable narrator, audition exact approved scripts, run Real-audio QC, then hand one human-approved narration to every downstream room.</p></div><div class="voice-health"><span class="health-light ${profile&&connector&&ffmpegReady?'ready':''}"></span><strong>${profile&&connector&&ffmpegReady?'Audition path ready':'Setup required'}</strong><small>${ffmpegReady?'FFmpeg validation online':'FFmpeg validation unavailable'} · ${connector?'provider tested':'provider not ready'}</small></div></section><div class="production-kpis"><div><span>Approved scripts</span><strong>${contents.length}</strong></div><div><span>Auditions</span><strong>${auditions.length}</strong></div><div><span>Current handoffs</span><strong>${handoffs.filter(item=>item.ready).length}</strong></div><div><span>${esc(usage.period)} voice capacity</span><strong>${(usage.settled+usage.reserved).toLocaleString()}</strong><small>characters admitted · ${money(usage.cost)} estimated</small></div></div><section class="production-card"><div class="production-card-head"><div><span class="micro-label">CHANNEL DEFAULT</span><h2>Narrator profile</h2></div>${action(profile?'Create new revision':'Configure narrator','configure-voice',family.id,'secondary')}</div>${profilePanel}</section><div class="production-split"><section class="production-card"><div class="production-card-head"><div><span class="micro-label">Inputs & gate</span><h2>Approved script queue</h2></div>${badge('Manual admission')}</div>${contentRows}<div class="job-stack">${jobRows}</div></section><section class="production-card"><div class="production-card-head"><div><span class="micro-label">Output handoff</span><h2>Primary narration</h2></div>${badge(handoffs.some(item=>item.ready)?'Ready for next room':'Blocked',handoffs.some(item=>item.ready)?'green':'gray')}</div>${handoffs.map(item=>`<div class="handoff-record"><span>${item.ready?'✓':'○'}</span><div><strong>${esc(state.contents.find(content=>content.id===item.contentId)?.title||item.contentId)}</strong><p>${item.ready?'Approved WAV, checksum and QC report are locked for scene timing.':'No current human-approved narration. Downstream rooms remain blocked.'}</p></div></div>`).join('')||'<p class="muted">The first approved script will create a handoff slot.</p>'}<div class="handoff-rule"><strong>Human approval</strong><p>Automated duration, silence, clipping, loudness and decode checks are necessary, not sufficient. A reviewer must compare takes and confirm complete intelligibility.</p></div></section></div><section class="production-card"><div class="production-card-head"><div><span class="micro-label">IMMUTABLE RESULTS</span><h2>Audition comparison</h2></div>${badge('No automatic winner')}</div><div class="audition-grid">${auditionCards}</div></section><section class="production-card"><div class="production-card-head"><div><span class="micro-label">DEPENDENCY LEDGER</span><h2>Downstream invalidations</h2></div>${badge(`${invalidations.length} recent`)}</div>${invalidations.length?`<div class="invalidation-list">${invalidations.map(item=>`<div><span>${esc(item.stage.replaceAll('_',' '))}</span><p>${esc(item.reason)}</p><time>${esc(date(item.createdAt))}</time></div>`).join('')}</div>`:'<p class="muted">No narration change has invalidated a downstream artifact yet.</p>'}</section><div class="production-notice"><strong>Spending boundary.</strong> A tested provider only proves access. Every potentially billable audition still requires an explicit click, character reservation and at most three deliberate paid attempts. There are no automatic retries or provider fallbacks.</div>`;
}
function production(){const families=activeFamilies();if(!families.length)return heading('Production panel','Channel-level settings, immutable outputs and explicit handoffs from room to room.')+`<section class="production-stage">${empty('Create a channel family first.','Every production setting and artifact is scoped to one family and inherited by its configured channel editions.',action('+ Create a family','new-family','','primary'))}</section>`;if(!families.some(item=>item.id===productionFamily))productionFamily=families[0].id;const family=families.find(item=>item.id===productionFamily),room=productionRooms.find(item=>item.id===productionRoom)||productionRooms[1];return heading('Channel production workspace','Set the production system once per channel family, inspect every output, and pass only approved artifacts to the next room.',`<a class="button secondary" href="/api/production-plan" target="_blank" rel="noopener">Architecture & safety ↗</a>`)+`<div class="production-toolbar"><div><label for="production-family">Channel family</label><select id="production-family">${families.map(item=>`<option value="${item.id}" ${item.id===family.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select></div><div class="production-context"><span>${esc(localeName(family.primaryLocale))}</span><span>${esc(family.format)}</span><span>${family.channels.length} channel edition${family.channels.length===1?'':'s'}</span><span>${family.cadence} / week</span></div></div><div class="production-console"><aside class="room-rail" aria-label="Production rooms">${productionRooms.map(item=>`<button class="room-tab ${item.id===room.id?'active':''}" data-production-room="${item.id}"><span class="room-number">${item.number}</span><span><strong>${esc(item.name)}</strong><small>${esc(item.summary)}</small></span><i class="room-state ${item.status}">${item.status==='live'?'LIVE':item.status==='active'?'ACTIVE':'LOCKED'}</i></button>`).join('')}</aside><div class="room-workspace">${room.id==='voice'?voiceRoom(family):room.id==='style'?styleRoom(family):productionBlueprint(room)}</div></div><div class="production-notice"><strong>Activation policy.</strong> Voice auditions are the only production-provider capability that can spend money in this milestone. The Style Library records decisions only. Visual generation, editing, rendering and production-provider spending in later rooms remain locked. Bounded Hermes script/research calls may already use configured provider capacity.</div>`;}
function connections(){return heading('Connections','Configure bounded planning connectors and track production tools still to connect.')+connectorSlots()+publicResearch()+`<div class="notice"><span class="notice-icon">◈</span><div><strong>Production permissions are separate.</strong><p>Read-only connector tests and bounded Hermes reasoning do not authorize channel ownership, unrestricted research, or publishing. Those production stages remain upcoming.</p></div></div><div class="section-heading"><h3>Production tools</h3></div><div class="connection-grid">${[
  ['YouTube','Not connected','Public lookup is available above. Per-channel OAuth authorization and private uploads are still upcoming.'],['Research & LLMs',state.capabilities.text==='bounded_hermes_candidates'?'Bounded Hermes':'Not connected',state.capabilities.text==='bounded_hermes_candidates'?'Connected for bounded script candidates and review-only synthesis from operator-saved evidence. Automatic source collection, approval, and publishing remain disabled.':'Save and test a restricted Hermes connector to enable bounded script candidates and review-only evidence synthesis.'],['Voice & translation','Upcoming','Each language needs a chosen locale, approved voice and quality checks. No translations or voices are generated yet.'],['FFmpeg',state.capabilities.ffmpeg==='executable_detected'?'Executable detected':state.capabilities.ffmpeg==='checking'?'Checking':'Not installed','Detection uses the supplied repository’s helper. Render and audio/video validation are a later milestone; detection alone is not a render test.']
].map(([name,status,description])=>`<article class="connection">${badge(status,['Executable detected','Bounded Hermes'].includes(status)?'green':'gray')}<h2>${name}</h2><p>${description}</p></article>`).join('')}</div><div class="section-heading"><h3>Reference and integration inventory</h3></div><div class="connection-grid">${state.build.repositories.map(r=>`<article class="connection">${badge(r.status,'orange')}<h2>${esc(r.name)}</h2><p>${esc(r.usage)}</p><small class="muted">${esc(r.license||'License not recorded')} · Revision ${esc(r.revision.slice(0,12))}</small><p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open repository ↗</a></p></article>`).join('')}</div>`;}
function publicResearch(){
  const yt=state.youtubeResearch, choices=state.connectors.filter(c=>c.provider==='youtube'&&c.hasKey);
  if(!choices.some(c=>c.id===selectedConnector)&&!(selectedConnector==='legacy'&&yt.saved))selectedConnector=choices[0]?.id||(yt.saved?'legacy':'');
  const disabled=researchPending||yt.busy, status='Public metadata only';
  return `<section class="panel"><div class="panel-header"><h2>YouTube public research</h2>${badge(status,yt.check?.status==='verified'?'green':'gray')}</div><div class="panel-body">
    <p>Look up a public channel before building competitor research. This does not sign in to a channel or allow uploads.</p>
    <details><summary>Set up your YouTube API key</summary><p>In your Google Cloud project, enable YouTube Data API v3 and create an API key restricted to that API. Enter the key here, never in chat or GitHub. Use a server IP restriction when your outbound IP is stable; browser-referrer restrictions do not fit this server request.</p><p><a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer">Open Google Cloud credentials ↗</a></p></details>
    <p class="muted">${yt.supported?'Saved keys are encrypted for your Windows account. Another Windows account or computer may require re-entry.':'Protected key storage requires Windows; the rest of planning remains available.'}</p>
    ${yt.saved?`<details><summary>Existing key from version 0.2</summary><form id="youtube-key-form"><label for="youtube-key">Replace existing YouTube key</label><div class="research-controls"><input id="youtube-key" name="key" type="password" autocomplete="off" spellcheck="false" minlength="30" maxlength="200" required placeholder="Paste replacement key"><button type="submit" class="button secondary">Save protected key</button><button type="button" data-action="forget-key" class="button text-button danger">Forget local key</button></div></form><p>Kept in its original protected file. Forgetting removes the local copy; Google revocation is separate.</p></details>`:''}
    <form id="youtube-channel-form"><label for="research-connector">Research connector</label><select id="research-connector" name="connector"><option value="">Choose a slot with a saved key</option>${choices.map(c=>`<option value="${c.id}" ${selectedConnector===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}${yt.saved?`<option value="legacy" ${selectedConnector==='legacy'?'selected':''}>Existing key from version 0.2</option>`:''}</select><label for="youtube-channel">Channel @handle, ID or URL</label><div class="research-controls"><input id="youtube-channel" name="channel" required maxlength="200" placeholder="@GoogleDevelopers" value="${esc(channelQuery)}"><button class="button primary" type="submit" ${!selectedConnector||disabled?'disabled':''}>${disabled?'Working…':'Look up channel'}</button></div></form>
    <p class="hint">Each click sends one channels.list request to Google using your project quota (documented cost: 1 unit). No background requests or automatic retries.</p>
    ${researchError?`<p class="form-error" role="alert">${esc(researchError)}</p>`:''}
    ${channelResult?`<article class="research-result"><div class="card-top"><h3>${esc(channelResult.title)}</h3>${badge('Public metadata','green')}</div><p class="muted">${esc(channelResult.id)} · Fetched ${esc(date(channelResult.fetchedAt))}</p><dl class="research-metrics"><div><dt>Subscribers (rounded)</dt><dd>${esc(channelResult.subscribers??'Unavailable')}</dd></div><div><dt>Total channel views</dt><dd>${esc(channelResult.views??'Unavailable')}</dd></div><div><dt>Public videos</dt><dd>${esc(channelResult.videos??'Unavailable')}</dd></div></dl><p>${esc(channelResult.description)}</p><p><a href="${esc(channelResult.sourceUrl)}" target="_blank" rel="noopener noreferrer">View source channel ↗</a></p><p class="muted">Results stay in this page session only. These totals do not reveal audience tier, retention, impressions, revenue or why a video ranks.</p></article>`:''}
  </div></section>`;
}
function progress(){const tasks=state.build.phases.flatMap(p=>p.tasks),done=tasks.filter(t=>t.status==='done').length;return heading('The build, step by step.','Completed work, validation evidence and remaining milestones in one place.',`<a class="button secondary" href="/api/progress" target="_blank" rel="noopener">Read detailed process file ↗</a>`)+`<section class="panel"><div class="panel-body"><div class="card-top"><h2>${done} of ${tasks.length} tracked work items complete</h2>${badge(state.build.milestone||'Current release','green')}</div><p class="muted">Work items vary in size. This count is a checklist, not a percentage of total engineering effort.</p><div class="progress-track"><progress value="${done}" max="${tasks.length}" aria-label="Completed work items">${done} of ${tasks.length}</progress></div><p class="muted">Next: ${esc(state.build.nextAction)}</p></div></section>${state.build.phases.map(p=>`<section class="progress-card"><div class="card-top"><h2>${esc(p.title)}</h2>${badge(p.tasks.every(t=>t.status==='done')?'Complete':p.tasks.some(t=>t.status==='done'||t.status==='testing')?'In progress':'Upcoming',p.tasks.every(t=>t.status==='done')?'green':'gray')}</div><p>${esc(p.goal)}</p>${p.tasks.map(t=>`<div class="task-row"><span class="task-symbol">${t.status==='done'?'✓':t.status==='testing'?'◌':'○'}</span><div><strong>${esc(t.id)} · ${esc(t.title)}</strong><p>${esc(t.evidence||t.remaining)}</p></div></div>`).join('')}</section>`).join('')}`;}
function render(){if(!state)return;const versionLabel=$('#app-version');if(versionLabel&&state.app?.version)versionLabel.textContent=`Version ${state.app.version} · ${state.build?.milestone||'Local control room'}`;const view=Object.hasOwn(viewNames,location.hash.slice(1))?location.hash.slice(1):'overview';$('#breadcrumb').textContent=viewNames[view];document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#main').innerHTML=({overview,families,research,studio,production,connections,progress,competitors:competitorsView,niches:nichesView}[view])();if(typeof applySwatches==='function')applySwatches($('#main'));if(typeof intelApplyMeters==='function')intelApplyMeters($('#main'));if(view==='production')requestAnimationFrame(()=>{const rail=$('.room-rail'),active=$('.room-tab.active');if(rail&&active&&rail.scrollWidth>rail.clientWidth)rail.scrollLeft=Math.max(0,active.offsetLeft-12);});}
function connectorSlots(){return `<section class="panel"><div class="panel-header"><h2>Your connector slots</h2>${action('+ Add connector','new-connector','','primary')}</div><div class="panel-body"><p>Create separate named slots for each provider or project. Testing verifies capabilities only. Separately gated script and research actions may use a tested Hermes slot; testing never authorizes channel ownership or publishing.</p><div class="connection-grid">${state.connectors.map(c=>`<article class="connection">${badge(c.busy?'Testing':c.test?.status==='passed'?'Test passed':c.test?.status==='failed'?'Test failed':c.test?.status==='not_implemented'?'Adapter pending':c.hasKey?'Key saved · Untested':'Needs setup',c.test?.status==='passed'?'green':'gray')}<h3>${esc(c.name)}</h3><p>${esc(state.connectorProviders[c.provider].name)} · v${c.revision}</p><p>${esc(c.notes)}</p><p>${esc(c.test?.message||state.connectorProviders[c.provider].test)}</p>${c.test?`<small>Tested ${esc(date(c.test.at))}</small>`:''}<div class="card-actions">${action('Edit','edit-connector',c.id,'text-button')}${action('Test','test-connector',c.id,'text-button')}${action('Delete','delete-connector',c.id,'text-button danger')}</div></article>`).join('')||'<p class="muted">No named slots yet. Add a connector to start.</p>'}</div><p class="hint">YouTube Test looks up @GoogleDevelopers (one API quota unit). Other live tests read metadata only. MCP/Reddit tests report adapter readiness without contacting a server. Deleting a slot removes its local saved key; revoke it separately at the provider if needed.</p></div></section>`;}
