function sourceField(source={}){const el=document.createElement('div');el.className='source-field';el.innerHTML=`<div class="source-heading"><strong>Source evidence</strong><button type="button" class="button text-button danger" data-remove-source>Remove</button></div><div class="form-grid"><label>Source title<input data-source="title" required minlength="2" maxlength="200" value="${esc(source.title)}"></label><label>Permission review<select data-source="permission"><option value="unreviewed">Not reviewed</option><option value="permitted" ${source.permission==='permitted'?'selected':''}>I verified permitted use</option></select></label><label class="full">Source URL<input data-source="url" type="url" required maxlength="2000" placeholder="https://…" value="${esc(source.url)}"></label><label class="full">What it supports and why you may use it<textarea data-source="notes" maxlength="3000" rows="2">${esc(source.notes)}</textarea></label></div>`;$('#source-fields').append(el);}
function contentDialog(id){const families=activeFamilies();if(!families.length){toast('Create or restore a family first.');return familyDialog();}const form=$('#content-form');form.reset();form.querySelector('.form-error').hidden=true;form.elements.id.value='';form.elements.revision.value='';$('#source-fields').replaceChildren();form.elements.familyId.innerHTML=families.map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('');form.elements.familyId.disabled=false;if(familyFilter)form.elements.familyId.value=familyFilter;const c=state.contents.find(c=>c.id===id);$('#content-heading').textContent=c?'Review or edit draft':'New content draft';$('#revision-warning').textContent=c?'Saving a revision returns this to Draft and clears its approval and storyboard. Close without saving to retain the current version.':'You can save incomplete drafts. Required checks must pass before review.';if(c){for(const key of ['id','revision','familyId','kind','title','angle','hook','script'])form.elements[key].value=c[key];form.elements.familyId.disabled=true;form.elements.rightsConfirmed.checked=c.rightsConfirmed;c.sources.forEach(sourceField);}$('#content-dialog').showModal();}
function evidenceDialog(id){const families=activeFamilies();if(!families.length){toast('Create a family first.',true);return;}const form=$('#evidence-form');form.reset();form.querySelector('.form-error').hidden=true;form.elements.familyId.innerHTML=families.map(item=>`<option value="${item.id}">${esc(item.name)}</option>`).join('');form.elements.familyId.value=researchFamily||families[0].id;form.elements.expiresAt.value=new Date(Date.now()+30*86400000).toISOString().slice(0,10);const item=state.researchEvidence.find(record=>record.id===id);$('#evidence-heading').textContent=item?'Edit research evidence':'Add research evidence';if(item){for(const field of ['id','revision','familyId','publisher','title','url','publishedAt','accessedAt','expiresAt','permission','analysisMode','notes','rightsNotes'])form.elements[field].value=item[field]??'';form.elements.familyId.disabled=true;}else{form.elements.id.value='';form.elements.revision.value='';form.elements.familyId.disabled=false;}$('#evidence-dialog').showModal();}
async function saveForm(form,save,successMessage){const submit=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');submit.disabled=true;error.hidden=true;try{await save();form.closest('dialog').close();await refresh();toast((typeof successMessage==='function'?successMessage():successMessage)||'Saved to your local workspace.');}catch(e){error.textContent=e.message;error.hidden=false;}finally{submit.disabled=false;}}
$('#family-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;saveForm(form,async()=>{const data=Object.fromEntries(new FormData(form));data.countries=data.countries.split(',').map(x=>x.trim()).filter(Boolean);data.locales=[data.primaryLocale,...data.additionalLocales.split(/[\s,]+/).map(x=>x.trim()).filter(Boolean)];delete data.primaryLocale;delete data.additionalLocales;data.competitors=data.competitors.split(/[\s,]+/).map(x=>x.trim()).filter(Boolean);data.monthlyBudget=Number(data.monthlyBudget);for(const field of ['cadence','monthlyTokenLimit','scriptTokenLimit','researchTokenLimit'])data[field]=Number(data[field]);data.revision=Number(data.revision);const saved=await api(data.id?`/api/families/${data.id}`:'/api/families',data,data.id?'PUT':'POST');const nicheEvaluationId=form.dataset.nicheEvaluationId;if(nicheEvaluationId&&!data.id){delete form.dataset.nicheEvaluationId;try{await api(`/api/niche-evaluations/${nicheEvaluationId}/link-family`,{familyId:saved.id});}catch(error){setTimeout(()=>toast(`Family saved, but it could not be linked to the niche: ${error.message}`,true),1200);}}});});
