setInterval(()=>{const audioPlaying=[...document.querySelectorAll('audio')].some(audio=>!audio.paused&&!audio.ended);if(!audioPlaying&&(state?.jobs.some(j=>['queued','running'].includes(j.status))||state?.researchJobs.some(j=>['queued','running'].includes(j.status))||state?.voiceJobs.some(j=>['queued','running'].includes(j.status))||(typeof intelBusy==='function'&&intelBusy()))&&!document.querySelector('dialog[open]')&&location.hash!=='#connections')refresh().catch(()=>{});},1500);
